{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver tredje betingelse forkert. Kilderne kræver \"meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde\". Svaret siger, at man \"næsten ikke kan have et studiejob\", og det er en anden og snævrere formulering, som ikke står i kilderne. Svaret nævner heller ikke, at tillægget gives sammen med SU-stipendium eller slutlån. Det angiver desuden \"SU-berettiget ... uddannelse\" i stedet for dansk EUD. Derudover tilføjer det et lavere fribeløb uden støtte."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Kritisk element 1 er kun delvist med. Svaret nævner ret til SU, men siger intet om, at tillægget udbetales sammen med SU-stipendium eller slutlån. Element 3 er delvist ændret til \"næsten ikke kan have et studiejob\" i stedet for meget betydelige begrænsninger i erhvervsevnen. Svaret nævner heller ikke eksplicit dansk EUD, kun \"erhvervsuddannelse\", og ikke at EUD er afgrænset til dansk EUD."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret angiver betingelserne for SU-handicaptillæg og forklarer, hvordan de vurderes. Det er direkte relevant for spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret henviser ikke til nogen identificerbar bestemmelse eller vejledning. Det nævner kun minSU og SU.dk generelt, og det er ikke en kildehenvisning til konkrete juridiske udsagn."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet en identificerbar kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet en identificerbar kilde, så det kan ikke vurderes, om kilden understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at man \"næsten ikke kan have et studiejob\", og det er en ikke understøttet tærskel. Det tilføjer også, at der gælder et lavere fribeløb, og at man søger via minSU. Intet af dette findes i det udleverede materiale. Journaloplysninger \"eller en udtalelse fra en behandler\" går desuden videre end kravet om lægefaglig dokumentation, der som minimum er journaler."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Rubrikken kræver ingen særskilt standardadvarsel. Svaret bruger \"som udgangspunkt\" og angiver, at SU kan bede om flere oplysninger. De kvalifikationer, der er krævet, er ikke tabt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende. Det forklarer, at en diagnose ikke alene afgør sagen, men at den konkrete påvirkning af arbejdsevnen vurderes, og det følger af betingelserne, som svaret selv opstiller."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør kravet om \"meget betydelige begrænsninger\" til en absolut tærskel (\"næsten ikke kan have et studiejob\"). Det siger også, at man \"skal ... vedlægge\" dokumentation som fx udtalelse fra en behandler, men kilden kræver lægefaglige oplysninger, som minimum journaler."
    }
  },
  "xhaile_coverage": {
    "A1": {
      "label": "partial",
      "reason": "Svaret kræver at man har ret til SU, men gengiver ikke de almindelige betingelser eller at tillægget gives sammen med SU-stipendium eller slutlån."
    },
    "A2": {
      "label": "partial",
      "reason": "Svaret nævner \"SU-berettiget videregående uddannelse eller erhvervsuddannelse\", men ikke eksplicit dansk EUD."
    },
    "A3": {
      "label": "partial",
      "reason": "Svaret nævner varig fysisk eller psykisk funktionsnedsættelse, men erstatter \"meget betydelige begrænsninger i evnen til erhvervsarbejde\" med \"næsten ikke kan have et studiejob\"."
    },
    "A4": {
      "label": "yes",
      "reason": "Svaret kræver indskrivning på en SU-berettiget uddannelse og ret til SU."
    },
    "A6": {
      "label": "no",
      "reason": "Svaret nævner ikke dansk EUD, herunder EUX, og heller ikke at erhvervslignende uddannelse i udlandet er udelukket."
    }
  },
  "overall_notes": "Svaret rammer hovedtrækkene, men har betydelige mangler og fejl: der er ingen kildehenvisninger, tærsklen for erhvervsevne er omformuleret, dansk EUD og udbetaling sammen med SU-stipendium eller slutlån er udeladt, og der er tilføjet uunderbyggede påstande om fribeløb og dokumentation."
}

